"""Read-only inventory of exact closed-job originals; no archive copies/refunds."""
import hashlib
import os
from pathlib import Path
import stat

from rlflow.store import atomic, canonical
from tools.r6_budget import observe
from tools.r6_job_handoff import close_terminal_job, read
from tools.r6_recovery import RecoveryError, checked, file_pin

DISK = 'output_actual_plus_unreleased_reservations_bytes'
MAX_FILES = 100000
MAX_MANIFEST_BYTES = 64 * 1024**2


def signature(s):
    return (s.st_dev, s.st_ino, s.st_mode, s.st_size, s.st_mtime_ns, s.st_ctime_ns)


def inventory(roots):
    """Hash all regular files, checking directory/file stability and special files.

    Hard links count once per pathname conservatively. Missing roots are explicit,
    never silently presented as complete evidence. Roots must not overlap.
    """
    resolved = {}
    for name, root in roots.items():
        root = Path(root)
        if not root.is_absolute() or root.is_symlink():
            raise RecoveryError('INVENTORY_ROOT_PATH')
        if root.resolve() != root:
            raise RecoveryError('INVENTORY_ROOT_ALIAS')
        resolved[name] = root
    paths = list(resolved.values())
    if any(a == b or a in b.parents or b in a.parents for i,a in enumerate(paths) for b in paths[i+1:]):
        raise RecoveryError('INVENTORY_ROOT_OVERLAP')
    files = []; directories = []; checked_files = []; missing = []
    for name, root in sorted(resolved.items()):
        if not root.exists():
            missing.append(name)
            continue
        stack = [root]
        while stack:
            directory = stack.pop(); before = directory.lstat()
            if not stat.S_ISDIR(before.st_mode):
                raise RecoveryError('INVENTORY_DIRECTORY_TYPE')
            directories.append((directory, signature(before)))
            for path in sorted(directory.iterdir()):
                info = path.lstat()
                if stat.S_ISDIR(info.st_mode):
                    stack.append(path)
                elif stat.S_ISREG(info.st_mode):
                    if len(files) >= MAX_FILES:
                        raise RecoveryError('INVENTORY_FILE_COUNT_BOUND')
                    digest = hashlib.sha256()
                    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
                    with os.fdopen(fd, 'rb') as stream:
                        opened = os.fstat(stream.fileno())
                        if signature(opened) != signature(info):
                            raise RecoveryError('INVENTORY_FILE_CHANGED')
                        for block in iter(lambda: stream.read(1024**2), b''):
                            digest.update(block)
                        if signature(os.fstat(stream.fileno())) != signature(info):
                            raise RecoveryError('INVENTORY_FILE_CHANGED')
                    checked_files.append((path, signature(info)))
                    files.append(dict(category=name, relative=str(path.relative_to(root)),
                        path=str(path), bytes=info.st_size, sha256=digest.hexdigest()))
                else:
                    raise RecoveryError('INVENTORY_SYMLINK_OR_SPECIAL_FILE')
                # Covers replacement/deletion after reading, not just changes to
                # an open inode that was unlinked while being hashed.
                if signature(path.lstat()) != signature(info):
                    raise RecoveryError('INVENTORY_FILE_CHANGED')
    for path, before in checked_files:
        if signature(path.lstat()) != before:
            raise RecoveryError('INVENTORY_FILE_CHANGED')
    for directory, before in directories:
        if signature(directory.lstat()) != before:
            raise RecoveryError('INVENTORY_DIRECTORY_CHANGED')
    if any(resolved[name].exists() for name in missing):
        raise RecoveryError('INVENTORY_MISSING_ROOT_APPEARED')
    files.sort(key=lambda row:(row['category'],row['relative']))
    return dict(roots={k:str(v) for k,v in resolved.items()},files=files,missing_roots=missing,
        total_original_bytes=sum(row['bytes'] for row in files),
        total_archive_copy_bytes=0,hardlink_accounting='Each pathname charged; no deduplication refund')


def record_inventory(journal, key, store):
    """Attach exact output observations atomically to the closed-job journal."""
    journal.require_writer()
    state = journal.read(); entry = state['events'][key]
    if state.get('current_job') not in (None, entry['identity']['job_id']):
        raise RecoveryError('OTHER_JOB_HANDOFF_ACTIVE')
    closure = close_terminal_job(journal, key, store)
    state = journal.read(); entry = state['events'][key]
    spec = read(checked(entry['request']['spec']))
    attempt = Path(spec['h1']['attempt'])
    # The exact submitted spec owns this attempt. Do not accept caller-selected
    # roots that could omit failed outputs or scan unrelated historical runs.
    expected_parent = store.root.resolve()/'attempts'
    if attempt.parent != expected_parent or not attempt.name or attempt.is_symlink():
        raise RecoveryError('INVENTORY_EXACT_ATTEMPT_ROOT')
    value = inventory({'job':store.root.resolve()/'jobs'/closure['job_id'], 'attempt':attempt})
    result = dict(schema_version='r6-job-inventory/1',event_key=key,job_id=closure['job_id'],
        closure=entry['closure'],spec=entry['request']['spec'],**value,
        output_inventory_complete=not value['missing_roots'],scientific_acceptance=False,
        native_status=closure['native_status'],native_exit_code=closure['native_exit_code'],
        metadata_accounting='Original job/attempt bytes only; controller metadata uses separate reserved capacity')
    data = canonical(result)+b'\n'
    if len(data) > MAX_MANIFEST_BYTES:
        raise RecoveryError('INVENTORY_MANIFEST_BOUND')
    path = journal.directory/'jobs'/key/'inventory.json'
    if entry.get('inventory'):
        if read(checked(entry['inventory'])) != result:
            raise RecoveryError('INVENTORY_REPLAY_DRIFT')
    elif path.exists():
        if read(path) != result:
            raise RecoveryError('INVENTORY_REPLAY_DRIFT')
    else:
        atomic(path,data)
    pin = file_pin(path)
    state['budget'] = observe(state['budget'],event_key=entry['identity'],
        resources={DISK:result['total_original_bytes']},evidence=pin)
    entry['inventory'] = pin
    violations = list(closure['budget_violations'])
    if result['total_original_bytes'] > entry['resources'].get(DISK, 0):
        violations.append('RESERVATION_EXCEEDED_'+DISK)
    entry['inventory_violations'] = violations
    if state['budget'].get('observed_cap_excess') or violations:
        state['status'] = 'JOB_BOUND_EXCEEDED'
    elif entry.get('stop_seen'):
        state['status'] = 'STOPPED_AFTER_OWNED_CLEANUP'
    elif entry.get('deadline_seen'):
        state['status'] = 'JOB_BOUND_EXCEEDED'
    elif not result['output_inventory_complete']:
        state['status'] = 'JOB_EVIDENCE_INCOMPLETE'
    else:
        state['status'] = 'INVENTORIED_PENDING_POSTRUN_AND_ANALYSIS'
    journal.save(state)
    return result

"""Two fixed R6 postrun queries with durable intent/receipt; never a live launcher."""
import argparse
import json
import os
from pathlib import Path
import selectors
import signal
import subprocess
import sys
import time

from rlflow import policy
from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from tools.r6_recovery import Journal, RecoveryError, checked, file_pin
from tools.r6_worker_processes import become_subreaper, cleanup
from tools.r6_model_worker import output_size, write

ROOT = Path(__file__).resolve().parents[1]
QUERIES = ('--query-gpu=index,name,driver_version,memory.total,memory.used,utilization.gpu',
           '--query-compute-apps=pid,process_name,used_gpu_memory')
CAP = 1024**2


def validate(journal, key):
    state = journal.read(); entry = state['events'][key]; request = entry['request']
    if (entry['kind'] != 'postrun' or sha(entry['identity']) != key
            or entry['identity']['input_sha256'] != sha(request)
            or set(request) != {'job_event_key','closure','inventory','executable','ordinal'}
            or type(request['ordinal']) is not int or request['ordinal'] not in (0,1)):
        raise RecoveryError('POSTRUN_REQUEST_IDENTITY')
    expected_event = 'POSTRUN:'+request['job_event_key']+':'+str(request['ordinal'])
    if (entry['identity']['event_id'] != expected_event or entry['identity']['role'] != 'postrun'
            or entry['identity']['goal_id'] != state['goal_id']):
        raise RecoveryError('POSTRUN_CANONICAL_EVENT')
    matching = [e for e in state['events'].values() if e['kind'] == 'postrun'
        and e['request'].get('job_event_key') == request['job_event_key']
        and e['request'].get('ordinal') == request['ordinal']]
    if len(matching) != 1:raise RecoveryError('POSTRUN_DUPLICATE_ORDINAL')
    job = state['events'][request['job_event_key']]
    if (job['kind'] != 'job' or job.get('closure') != request['closure']
            or job.get('inventory') != request['inventory']
            or job['identity']['job_id'] != entry['identity']['job_id']):
        raise RecoveryError('POSTRUN_JOB_BINDING')
    close = json.loads(checked(request['closure']).read_text())
    inv = json.loads(checked(request['inventory']).read_text())
    if (close['job_id'] != entry['identity']['job_id'] or close['event_key'] != request['job_event_key']
            or inv['job_id'] != close['job_id'] or inv['closure'] != request['closure']):
        raise RecoveryError('POSTRUN_CLOSURE_IDENTITY')
    for pin in close['evidence'].values():checked(pin)
    if entry['resources'].get('output_actual_plus_unreleased_reservations_bytes',0) < CAP+65536:
        raise RecoveryError('POSTRUN_OUTPUT_RESERVATION')
    spec = json.loads(checked(job['request']['spec']).read_text())
    executable = checked(request['executable'])
    if spec['backend'] == 'real':
        if state['budget']['capacity_pass'] is not True:
            raise RecoveryError('POSTRUN_REAL_CAPACITY_REQUIRED')
        from training_workloads.unified_h1.config import resource_binding_pins
        pins = resource_binding_pins()
        if request['executable'] != {'path':pins['nvidia_smi_path'],'sha256':pins['nvidia_smi_sha256']}:
            raise RecoveryError('POSTRUN_FROZEN_EXECUTABLE')
    elif (spec['backend'] != 'runner_cpu' or state['goal_id'] != 'R6-CPU-TEST-FIXTURE'
            or not executable.is_relative_to(journal.directory.parent.resolve())):
        raise RecoveryError('POSTRUN_CPU_FIXTURE_BOUNDARY')
    return entry, executable


def stop_paths(journal):
    return journal.stopped() + policy.stopped(ROOT/'coordination/research') + [str(p) for p in
        (journal.directory.parent/'STOP',ROOT/'STOP',ROOT/'coordination/STOP',
         ROOT/'coordination/commander/STOP',ROOT/'coordination/executor/STOP') if p.exists()]


def run_query(journal, key):
    """Separate bounded worker persists its identity before the query side effect."""
    entry, executable = validate(journal,key); request = entry['request']
    if not entry.get('dispatch_claim') or checked(entry['dispatch_claim']['worker']) != Path(__file__).resolve():
        raise RecoveryError('POSTRUN_DISPATCH_CLAIM_REQUIRED')
    directory = journal.directory/'postrun'/key;directory.mkdir(parents=True,exist_ok=True)
    if any(directory.iterdir()):raise RecoveryError('POSTRUN_EXISTING_WORKER_NO_RETRY')
    fd = os.open(directory/'ONCE',os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
    try:os.write(fd,b'one postrun query\n');os.fsync(fd)
    finally:os.close(fd)
    worker = identity(os.getpid())
    write(directory/'worker.json',{'identity':worker,'event_key':key},CAP-65536)
    argv = [str(executable),QUERIES[request['ordinal']],'--format=csv,noheader,nounits']
    write(directory/'request.json',{'request':request,'argv':argv},CAP-65536)
    proc = None; child = None; error = None; code = -1; cleaned = None
    start = time.monotonic(); interrupted = []
    previous = {s:signal.signal(s,lambda signum,frame:interrupted.append(signum)) for s in (signal.SIGTERM,signal.SIGINT)}
    try:
        if stop_paths(journal):raise RecoveryError('STOP_BEFORE_POSTRUN')
        become_subreaper()
        with (directory/'stdout').open('xb') as stdout,(directory/'stderr').open('xb') as stderr,selectors.DefaultSelector() as selector:
            proc = subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                start_new_session=True,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES=''))
            child = identity(proc.pid)
            if child is None:raise RecoveryError('POSTRUN_CHILD_EXIT_BEFORE_IDENTITY')
            write(directory/'child.json',{'identity':child,'event_key':key},CAP-65536)
            selector.register(proc.stdout,selectors.EVENT_READ,stdout)
            selector.register(proc.stderr,selectors.EVENT_READ,stderr)
            while selector.get_map() or proc.poll() is None:
                if interrupted or stop_paths(journal):raise RecoveryError('STOP_DURING_POSTRUN')
                if time.monotonic()-start > 15:raise RecoveryError('POSTRUN_TIMEOUT')
                for ready,_ in selector.select(.1):
                    data = os.read(ready.fileobj.fileno(),65536)
                    if not data:
                        selector.unregister(ready.fileobj);ready.fileobj.close();continue
                    if output_size(directory)+len(data) > CAP-65536:
                        raise RecoveryError('POSTRUN_OUTPUT_CAP_BEFORE_WRITE')
                    ready.data.write(data);ready.data.flush()
            proc.wait();code = proc.returncode
            if code != 0:raise RecoveryError('POSTRUN_NONZERO_EXIT')
    except BaseException as exc:error = repr(exc)
    finally:
        if proc is not None:
            try:cleaned = cleanup(proc);code = proc.returncode
            except BaseException as exc:error = str(error)+'; '+repr(exc)
        for sig,handler in previous.items():signal.signal(sig,handler)
    for name in ('stdout','stderr'):
        path = directory/name
        if path.exists():
            with path.open('rb') as stream:os.fsync(stream.fileno())
    result = dict(event_key=key,request_sha256=sha(request),process=worker,child_identity=child,
        exit_code=code if type(code)is int else -1,error=error,cleanup=cleaned,ordinal=request['ordinal'],
        job_id=entry['identity']['job_id'],elapsed_seconds=time.monotonic()-start,
        stdout=file_pin(directory/'stdout') if (directory/'stdout').exists() else None,
        stderr=file_pin(directory/'stderr') if (directory/'stderr').exists() else None,
        automatic_retry=False,scientific_acceptance=False)
    write(directory/'receipt.json',result,CAP)
    return 0 if code == 0 and error is None else 1


def verified_receipt(journal,key):
    entry,_ = validate(journal,key)
    receipt = json.loads(checked(entry['receipt']).read_text())
    if (receipt.get('event_key') != key or receipt.get('request_sha256') != sha(entry['request'])
            or receipt.get('job_id') != entry['identity']['job_id']
            or receipt.get('ordinal') != entry['request']['ordinal']):
        raise RecoveryError('POSTRUN_RECEIPT_IDENTITY')
    for name in ('stdout','stderr'):
        if receipt.get(name):checked(receipt[name])
    if (receipt.get('exit_code') != 0 or receipt.get('error') is not None
            or (receipt.get('cleanup') or {}).get('status') != 'VERIFIED_NO_OWNED_DESCENDANTS'):
        raise RecoveryError('POSTRUN_FAILED_PRESERVED')
    if (owns(receipt.get('process')) or owns(receipt.get('child_identity'))
            or any(owns(i) for i in receipt['cleanup'].get('observed_identities',[]))):
        raise RecoveryError('POSTRUN_OWNED_PROCESS_ALIVE')
    return receipt


def postrun_handoff(journal,key,*,poll_seconds=1):
    """Recover one exact query. An unbound dispatch claim is never retried."""
    journal.require_writer()
    if type(poll_seconds) not in (int,float) or not 0 < poll_seconds <= 60:
        raise RecoveryError('POSTRUN_POLL_INTERVAL')
    entry,_ = validate(journal,key)
    if entry.get('receipt'):return verified_receipt(journal,key)
    directory = journal.directory/'postrun'/key;proc = None
    if not entry.get('dispatch_claim'):
        journal.guard()
        if stop_paths(journal):raise RecoveryError('STOP_BEFORE_POSTRUN')
        if directory.exists() or entry.get('process') or entry['status'] != 'INTENT':
            raise RecoveryError('POSTRUN_UNCLAIMED_SIDE_EFFECT')
        # Check normal cleanup at dispatch, not just a historical boolean.
        from tools.r6_job_handoff import no_model_workers
        state = journal.read();jobentry = state['events'][entry['request']['job_event_key']]
        # The prior close record binds Store output; checking every recorded
        # identity here prevents postrun while an owned process remains alive.
        close = json.loads(checked(jobentry['closure']).read_text())
        records = {name:json.loads(checked(pin).read_text()) for name,pin in close['evidence'].items()}
        ids = [records['lifeguard-ack.json']['owner'],records['lifeguard-ready.json']['identity'],
            records['process-identity.json'],*records['descendant-ledger.json']['descendants'],
            *records['descendant-cleanup.json']['discovered']]
        if any(owns(i) for i in ids):raise RecoveryError('POSTRUN_JOB_STILL_ALIVE')
        no_model_workers(journal)
        entry['dispatch_claim'] = {'controller':identity(os.getpid()),'worker':file_pin(Path(__file__))}
        state['events'][key] = entry;state['status'] = 'POSTRUN_QUERY';journal.save(state)
        proc = subprocess.Popen([sys.executable,'-B','-m','tools.r6_postrun',str(journal.directory.resolve()),key],
            cwd=ROOT,stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
            start_new_session=True,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1',PYTHONPATH='.:tools/rlflow',CUDA_VISIBLE_DEVICES=''))
        ident = identity(proc.pid)
        if ident is not None:journal.bind_process(key,ident)
    while True:
        if proc is not None:proc.poll()
        entry = journal.read()['events'][key]
        workerpath = directory/'worker.json'
        if entry['process'] is None and workerpath.exists():
            worker = json.loads(workerpath.read_text())
            if worker['event_key'] != key:raise RecoveryError('POSTRUN_WORKER_EVENT')
            if owns(worker['identity']):journal.bind_process(key,worker['identity'])
        action = journal.observe(key,receipt_path=directory/'receipt.json')['action']
        if action == 'ACCEPT_RECEIPT':
            journal.consume(key,directory/'receipt.json')
            return verified_receipt(journal,key)
        if action == 'ALREADY_CONSUMED':return verified_receipt(journal,key)
        if action == 'RECONCILE':raise RecoveryError('POSTRUN_AMBIGUOUS_NO_RETRY')
        if action not in ('WAIT_OWNED_WORKER','WAIT_OWNED_EXIT','CANCEL_OWNED'):
            raise RecoveryError('POSTRUN_UNEXPECTED_OBSERVATION')
        time.sleep(poll_seconds)


def register_postruns(journal, job_key, executable, *, free_disk_bytes):
    """Reserve both fixed ordinals before launch; changed requests cannot rerun one."""
    journal.guard()
    state = journal.read(); job = state['events'][job_key]
    if job['kind'] != 'job' or not job.get('closure') or not job.get('inventory'):
        raise RecoveryError('POSTRUN_CLOSED_INVENTORIED_JOB_REQUIRED')
    keys = []
    for ordinal in (0,1):
        request = dict(job_event_key=job_key,closure=job['closure'],inventory=job['inventory'],
            executable=executable,ordinal=ordinal)
        for prior in journal.read()['events'].values():
            if (prior['kind'] == 'postrun' and prior['request'].get('job_event_key') == job_key
                    and prior['request'].get('ordinal') == ordinal and prior['request'] != request):
                raise RecoveryError('POSTRUN_ORDINAL_ALREADY_BOUND')
        event = dict(goal_id=state['goal_id'],event_id='POSTRUN:'+job_key+':'+str(ordinal),
            job_id=job['identity']['job_id'],input_sha256=sha(request),role='postrun')
        key,_ = journal.intent(event,kind='postrun',request=request,
            resources={'output_actual_plus_unreleased_reservations_bytes':CAP+65536},
            purpose=job['purpose'],free_disk_bytes=free_disk_bytes)
        validate(journal,key);keys.append(key)
    return keys


def complete_postruns(journal, job_key, keys, *, poll_seconds=1):
    journal.require_writer()
    if len(keys) != 2 or len(set(keys)) != 2:raise RecoveryError('POSTRUN_TWO_EXACT_EVENTS')
    for ordinal,key in enumerate(keys):
        entry,_ = validate(journal,key)
        if entry['request']['ordinal'] != ordinal or entry['request']['job_event_key'] != job_key:
            raise RecoveryError('POSTRUN_ORDINAL_ORDER')
    for key in keys:postrun_handoff(journal,key,poll_seconds=poll_seconds)
    state = journal.read(); job = state['events'][job_key]
    result = dict(schema_version='r6-postrun-summary/1',job_event_key=job_key,job_id=job['identity']['job_id'],
        closure=job['closure'],inventory=job['inventory'],postrun_queries_used=2,
        receipts=[state['events'][key]['receipt'] for key in keys],
        postrun_complete=True,scientific_acceptance=False)
    path = journal.directory/'jobs'/job_key/'postrun-summary.json'
    if job.get('postrun'):
        if json.loads(checked(job['postrun']).read_text()) != result:raise RecoveryError('POSTRUN_SUMMARY_DRIFT')
    elif path.exists():
        if json.loads(path.read_text()) != result:raise RecoveryError('POSTRUN_SUMMARY_DRIFT')
    else:
        data = canonical(result)+b'\n'
        if len(data) > 65536:raise RecoveryError('POSTRUN_SUMMARY_CAP')
        atomic(path,data)
    job['postrun'] = file_pin(path)
    state['status'] = ('STOPPED_AFTER_OWNED_CLEANUP' if stop_paths(journal) or job.get('stop_seen')
        else 'JOB_BOUND_EXCEEDED' if job.get('deadline_seen') or job.get('inventory_violations') or state['budget'].get('observed_cap_excess')
        else 'JOB_EVIDENCE_INCOMPLETE' if not json.loads(checked(job['inventory']).read_text())['output_inventory_complete']
        else 'POSTRUN_COMPLETE_PENDING_ANALYSIS')
    journal.save(state)
    return result


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('directory',type=Path);parser.add_argument('event_key');args=parser.parse_args()
    raise SystemExit(run_query(Journal(args.directory.resolve()),args.event_key))

"""CPU-only R6 budget checks. Caller holds the single controller writer lock.

No Store permission, submission, settlement or budget refund occurs here.
Reservations remain charged even when an attempt or worker fails.
"""
import copy
import math


class BudgetError(ValueError):
    pass


def amount(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise BudgetError('Resource amount must be numeric')
    if not math.isfinite(value) or value < 0:
        raise BudgetError('Resource amount must be finite and nonnegative')
    return value


def charged(reservation, caps):
    """Conservative charge: max(reserved, every pinned observation), never sum twice."""
    result = {}
    for resources in [reservation['resources'], *[o['resources'] for o in reservation.get('observations', [])]]:
        for resource, value in resources.items():
            if resource not in caps:
                raise BudgetError('Unknown resource: ' + resource)
            result[resource] = max(result.get(resource, 0), amount(value))
    return result


def totals(ledger, *, enforce_caps=True):
    caps = ledger['caps']
    result = {k: amount(ledger['used'][k]) for k in caps}
    seen = set()
    for reservation in ledger['reservations']:
        key = reservation['event_key']
        if key in seen:
            raise BudgetError('Duplicate reservation event')
        seen.add(key)
        for resource, value in charged(reservation, caps).items():
            result[resource] += value
    for resource, value in result.items():
        if enforce_caps and value > amount(caps[resource]):
            raise BudgetError('Cap exceeded: ' + resource)
    return result


def reserve(ledger, *, event_key, resources, purpose, free_disk_bytes):
    """Return a new ledger; identical replays don't spend again, drift fails.

    event_key binds goal, event, job, input hash and role. Final/recovery use
    of protected capacity is explicit. Ordinary development cannot borrow it.
    Disk check subtracts all outstanding output reservations conservatively.
    """
    required = {'goal_id', 'event_id', 'job_id', 'input_sha256', 'role'}
    if set(event_key) != required or event_key['goal_id'] != ledger['goal_id']:
        raise BudgetError('Incomplete event identity')
    if not all(isinstance(v, str) and v for v in event_key.values()):
        raise BudgetError('Empty event identity')
    digest = event_key['input_sha256']
    if len(digest) != 64 or any(c not in '0123456789abcdef' for c in digest):
        raise BudgetError('Invalid input hash')
    if purpose not in {'development', 'confirmation_delivery', 'repair', 'final_review'}:
        raise BudgetError('Unknown reservation purpose')
    key = tuple(event_key[k] for k in sorted(required))
    # JSON round trips preserve this stable string; tuples are not persisted.
    import json
    key = json.dumps(key, separators=(',', ':'))
    entry = {'event_key': key, 'identity': event_key, 'resources': resources, 'purpose': purpose}
    for prior in ledger['reservations']:
        if prior['event_key'] == key:
            if {k: prior[k] for k in entry} != entry:
                raise BudgetError('Reservation replay drift')
            totals(ledger)
            return copy.deepcopy(ledger)
    candidate = copy.deepcopy(ledger)
    candidate['reservations'].append(copy.deepcopy(entry))
    usage = totals(candidate)
    if purpose == 'development':
        for resource, protected in ledger['protected_confirmation_delivery_repair'].items():
            # Protected use cannot accidentally become available to exploration.
            dev_used = amount(ledger['used'][resource])
            dev_used += sum(charged(r, ledger['caps']).get(resource, 0) for r in candidate['reservations']
                            if r['purpose'] == 'development')
            if dev_used > ledger['caps'][resource] - amount(protected):
                raise BudgetError('Protected capacity: ' + resource)
    model_cap = ledger['caps']['automatic_model_sessions']
    other_models = amount(ledger['used']['automatic_model_sessions']) + sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                       for r in candidate['reservations']
                       if r['purpose'] not in {'repair', 'final_review'})
    if other_models > model_cap - sum(ledger['protected_model_sessions'].values()):
        raise BudgetError('Protected review/repair sessions')
    for protected_role, count in ledger['protected_model_sessions'].items():
        outside_role = amount(ledger['used']['automatic_model_sessions'])
        outside_role += sum(charged(r, ledger['caps']).get('automatic_model_sessions', 0)
                            for r in candidate['reservations']
                            if r['purpose'] != protected_role)
        if outside_role > model_cap - count:
            raise BudgetError('Protected model role: ' + protected_role)
    disk_key = 'output_actual_plus_unreleased_reservations_bytes'
    if amount(free_disk_bytes) - usage[disk_key] < ledger['disk_free_floor_bytes']:
        raise BudgetError('Disk floor after reservations')
    return candidate


def observe(ledger, *, event_key, resources, evidence):
    """Record pinned actuals, including overruns; never mutate/refund reservations.

    Actual cap breaches must be durable even though further reserve() will fail.
    Caller verifies evidence bytes and atomically saves this result with its event.
    """
    if (not isinstance(evidence, dict) or set(evidence) != {'path', 'sha256'}
            or not isinstance(evidence['path'], str) or not evidence['path']
            or not isinstance(evidence['sha256'], str) or len(evidence['sha256']) != 64
            or any(c not in '0123456789abcdef' for c in evidence['sha256'])):
        raise BudgetError('Observation evidence pin')
    if not isinstance(resources, dict) or not resources:
        raise BudgetError('Observation resources required')
    charged({'resources': resources}, ledger['caps'])
    result = copy.deepcopy(ledger)
    entries = [r for r in result['reservations'] if r['identity'] == event_key]
    if len(entries) != 1:
        raise BudgetError('Observation requires one exact reservation')
    observations = entries[0].setdefault('observations', [])
    new = {'resources': copy.deepcopy(resources), 'evidence': copy.deepcopy(evidence)}
    for old in observations:
        if old['evidence'] == evidence:
            if old != new:
                raise BudgetError('Observation replay drift')
            return result
    observations.append(new)
    usage = totals(result, enforce_caps=False)
    result['observed_cap_excess'] = {k: v-result['caps'][k] for k, v in usage.items() if v > result['caps'][k]}
    return result

"""R6 recovery journal, reusing rlflow atomic persistence and process identity.

This is not a launcher. The controller must hold this lock before calling any
mutation. An intent without authoritative completion never authorizes a retry.
"""
from contextlib import contextmanager
from pathlib import Path
import fcntl
import hashlib
import json
import os

from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from tools.r6_budget import reserve


class RecoveryError(RuntimeError):
    pass


def file_pin(path):
    path = Path(path).resolve()
    with path.open('rb') as stream:
        digest = hashlib.file_digest(stream, 'sha256').hexdigest()
    return {'path': str(path), 'sha256': digest}


def checked(pin):
    path = Path(pin['path'])
    if path.is_symlink() or file_pin(path) != pin:
        raise RecoveryError('PIN_DRIFT')
    return path


class Journal:
    def __init__(self, directory, stop_paths=()):
        self.directory = Path(directory)
        self.path = self.directory / 'state.json'
        self.stop_paths = [self.directory / 'STOP', *map(Path, stop_paths)]
        self._lock = None
        self._owner_pid = None

    @contextmanager
    def writer(self):
        if self._lock is not None:
            raise RecoveryError('NESTED_WRITER')
        self.directory.mkdir(parents=True, exist_ok=True)
        with (self.directory / 'writer.lock').open('a') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            self._lock, self._owner_pid = lock, os.getpid()
            try:
                yield self
            finally:
                self._lock = self._owner_pid = None
                fcntl.flock(lock, fcntl.LOCK_UN)

    def require_writer(self):
        if self._lock is None or self._owner_pid != os.getpid():
            raise RecoveryError('SINGLE_WRITER_REQUIRED')

    def stopped(self):
        return [str(p) for p in self.stop_paths if p.exists()]

    def guard(self):
        self.require_writer()
        if self.stopped():
            raise RecoveryError('STOP_NEW_ACTIONS')

    def read(self):
        return json.loads(self.path.read_text())

    def save(self, state):
        self.require_writer()
        atomic(self.path, canonical(state) + b'\n')

    def initialize(self, budget):
        self.guard()
        if self.path.exists():
            raise RecoveryError('USE_EXISTING_STATE')
